import{_ as t,o as s,c as o,a2 as a}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Open Cube OS","description":"","frontmatter":{},"headers":[],"relativePath":"zh/root/README.md","filePath":"zh/root/README.md"}'),n={name:"zh/root/README.md"};function d(r,e,l,c,i,p){return s(),o("div",null,[...e[0]||(e[0]=[a(`<div align="center"><h1 id="open-cube-os" tabindex="-1">Open Cube OS <a class="header-anchor" href="#open-cube-os" aria-label="Permalink to &quot;Open Cube OS&quot;">​</a></h1><p><strong>一个从零写起、直接启动进 Ring 3 的 x86_64 内核。</strong></p><p>当前开发预览：<strong>3.0.0-WP-l1apps-merge</strong>——OCBL 引导加载器、纯 L0 服务内核（L0 里没有 shell、没有 TUI、没有 IME）、<code>ocos/l1apps/</code> 下的 <strong>284 个 Ring-3 程序</strong>——现在围绕 <strong>8 个合并大应用</strong>组织（<code>update</code> / <code>disk-tool</code> / <code>net-tool</code> / <code>sound-tool</code> / <code>files</code> / <code>sysdiag</code> / <code>hwinfo</code> / <code>power</code>），每一个 既是意图向导，<em>又</em>是其下每条经典命令的逐字分发。稳定线： <strong>2.2.0</strong>（2.x 世界的最后一个正式发布，留作参考与真机 稳定性）。见 <a href="https://github.com/cubestudio-dev/OpenCubeOS/releases" target="_blank" rel="noreferrer">Releases</a>。</p><p><code>ush&gt;</code> 是提示符。一切皆可扩展。</p><p><a href="https://ocos.cubestudio.cn/" target="_blank" rel="noreferrer">官网</a> · <a href="https://ocos.cubestudio.cn/docs/" target="_blank" rel="noreferrer">文档</a> · <a href="#downloads">下载</a> · <a href="./BUILDING.html">构建</a> · <a href="./ARCHITECTURE.html">架构</a> · <a href="./INTERFACES.html">接口参考</a></p></div><hr><h2 id="它是什么" tabindex="-1">它是什么 <a class="header-anchor" href="#它是什么" aria-label="Permalink to &quot;它是什么&quot;">​</a></h2><p>Open Cube OS 是 <strong>L0 + L1</strong>：</p><ul><li><p><strong>L0 提供服务。</strong> 纯服务内核——启动链、核心机制、驱动、 根服务和编号接口。3.0.0-WP03 彻底删除了 L0 用户面（2.x 的 <code>oc&gt;</code> 恢复 shell、内核内 TUI、输入法引擎）；L0 在 <code>L0 ready, waiting for L1</code> 完成启动，把机器交给默认的 Ring-3 入口。</p></li><li><p><strong>L1 使用服务。</strong> <code>ocos/l1apps/</code> 下的 284 个 Ring-3 程序 （一条命令 = 一个应用 = 一个文件夹）：默认启动项是 <code>ush</code> 用户 shell（<strong>296 条命令 = 284 个注册表应用 + 12 个 内建，L0 里零条命令</strong>）、TUI 桌面、编辑器、中文控制台 + 拼音 IME——以及给整个命令面装上按意图驱动前门的 8 个 合并大应用：带自动检测与跨域修复的无参向导（<code>update</code> 向导在真正检查更新之前，先通过 DHCP 修复缺失的 IP、 通过 <code>abdisk</code> 修复缺失的 A/B 磁盘）、<code>direct</code> 显式透传， 以及零功能损失的经典逐字分发。</p></li><li><p><strong>不是 Linux 分支。</strong> Apache 2.0 下横跨 764 个文件的 158,474 行原创 C/汇编（验证：见下文<em>数据</em>）。</p></li><li><p><strong>PC 平台走到哪就启动到哪：</strong> 经 OCBL 的单一混合 BIOS + UEFI ISO——树内引导加载器（512 字节实模式 stage 1 / EFI 入口、16→32→64 位长模式、动态磁盘扫描）——512 MiB 内存即可舒适运行，磁盘可选。</p></li><li><p><strong>一个真正的内核：</strong> 抢占式调度器、4 级分页、带 54 个 系统调用的 Ring-3 用户程序、FAT32/exFAT/ext4/ramfs 之上 的 VFS、带 TLS 1.2/1.3 和 SSH（客户端<em>和</em>服务器）的完整 TCP/IP 协议栈、从 NVMe 到 xHCI 再到 ACPI AML 的 15 个 驱动家族、崩溃转储、硬件看门狗（Intel TCO / ACPI WDAT）、OTA A/B 更新，以及 WP07a 启动状态监视器：六个 启动阶段记录进一个固定状态区、逐阶段看门狗预算，外加 一条重启后由 OCIRE 读取、用于打印停滞点与修复建议的 BOOT_FAILED 事后记录。</p></li><li><p><strong>设计上诚实：</strong> 若 Ring-3 世界无法启动，L0 会明说并 停机——指引就是重启或 OCBL 启动菜单（故意不设可供 回退的 L0 shell）。</p></li></ul><p>两层架构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L0  OCOS (ocos/)          kernel + drivers + root services + the</span></span>
<span class="line"><span>                          numbered L1SVC ABI - no shell, no TUI</span></span>
<span class="line"><span>L1  the world (ocos/l1apps/)  284 programs: ush, TUI, editor, IME,</span></span>
<span class="line"><span>                          one command per app, and the 8 merged</span></span>
<span class="line"><span>                          mega-apps (296 commands total)</span></span></code></pre></div><h2 id="亮点" tabindex="-1">亮点 <a class="header-anchor" href="#亮点" aria-label="Permalink to &quot;亮点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>领域</th><th>你得到什么</th></tr></thead><tbody><tr><td>启动</td><td>OCBL——树内引导加载器：混合 BIOS + UEFI ISO、16→32→64 位长模式、动态磁盘扫描、带 10 秒倒计时的启动菜单（3.0.0 链中没有 GRUB）</td></tr><tr><td>内存</td><td>引导内存映射之上的 PMM 位图、4 级 VMM、经 #PF 真实增长的 kmalloc 堆</td></tr><tr><td>CPU</td><td>抢占式优先级 + 轮转调度器、带 IST 栈的 256 门 IDT、100 Hz PIT + HPET/PM-timer/TSC 时源、LAPIC</td></tr><tr><td>Ring 3</td><td>ELF 加载器、54 个系统调用、信号、fork/exec/管道/select/mmap、动态链接（树内 ld.so、PIE、dlsym）；SYS_L1SVC + SYS_NETCMD 服务桥</td></tr><tr><td>存储</td><td>AHCI、ATA/ATA-DMA、NVMe、virtio-blk、USB MSC、SCSI（LSI）；带 LFN 的 FAT32、exFAT、ext4、ramfs；GPT/MBR 分区；A/B 槽位</td></tr><tr><td>网络</td><td>e1000/e1000e/igb/ixgbe/rtl8139/rtl8169 家族/BCM57xx 驱动、带拥塞控制的 ARP/IPv4/ICMP/UDP/DNS/TCP、套接字、防火墙、HTTPS 客户端（TLS 1.2/1.3 + X.509 链）、SSH 客户端 + sshd</td></tr><tr><td>USB</td><td>UHCI、OHCI、EHCI、xHCI；大容量存储、HID、串口、音频类</td></tr><tr><td>媒体</td><td>HDA / AC97 / SB16 / ES1370 / virtio sound；带 MJPEG 的 UVC 摄像头</td></tr><tr><td>平台</td><td>ACPI（FADT/DSDT/MCFG、真实 AML 遍历器、S3 挂起/恢复）、Intel TCO + ACPI WDAT 硬件看门狗、HPET、i2c/SMBus</td></tr><tr><td>Shell</td><td>ush（Ring 3，默认启动项）：284 个注册表应用 + 12 个内建，带管道/重定向/环境变量/别名/作业；L0 里零条命令</td></tr><tr><td>大应用</td><td>8 个合并应用（<code>update</code>、<code>disk-tool</code>、<code>net-tool</code>、<code>sound-tool</code>、<code>files</code>、<code>sysdiag</code>、<code>hwinfo</code>、<code>power</code>）：带跨域修复的意图向导 + <code>direct</code> 透传 + 经典逐字分发；破坏性路径由重输 + y/N 双重确认防护</td></tr><tr><td>TUI</td><td>桌面、任务栏、菜单、表单、编辑器、系统应用——依托 L1SVC tui 服务的 Ring-3 程序，外加中文控制台层（16x16 字体、拼音 IME）</td></tr><tr><td>可靠性</td><td>崩溃转储到串口 + /etc crashlog、带轮转 + 级别 + 过滤的内核日志、健康监视器（CPU/内存/任务/IO + JSON 导出）、带 SHA256 + 签名与回滚的 OTA</td></tr><tr><td>OCBL</td><td>树内引导加载器（<code>ocbl/</code>）：BIOS stage 1（El Torito / MBR）+ UEFI 入口、启动菜单、安装器目标（<code>ocbl-install</code>）</td></tr><tr><td>OCIRE</td><td>独立恢复内核（<code>ocire/</code>）：与 OCOS 零代码共享的第二个 L0，从自己的 ISO 独立启动，把镜像存放在 OCOS 无法读写的隔离分区（见 <code>docs/dev/ocire.md</code>）</td></tr></tbody></table><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># build (Linux): needs gcc nasm xorriso mtools grub-common</span></span>
<span class="line"><span>#               grub-pc-bin grub-efi-amd64-bin zip python3</span></span>
<span class="line"><span>tools/build.sh iso</span></span>
<span class="line"><span></span></span>
<span class="line"><span># run it</span></span>
<span class="line"><span>qemu-system-x86_64 -m 512M -cdrom build/opencube.iso \\</span></span>
<span class="line"><span>    -netdev user,id=n1 -device e1000,netdev=n1</span></span>
<span class="line"><span></span></span>
<span class="line"><span># inside the guest (the default boot entry is the ring-3 ush shell)</span></span>
<span class="line"><span>ush&gt; hwinfo            (wizard: what hardware is this machine?)</span></span>
<span class="line"><span>ush&gt; update            (wizard: network -&gt; A/B -&gt; DNS -&gt; check -&gt; install)</span></span>
<span class="line"><span>ush&gt; help -a           (all 284 registry programs)</span></span>
<span class="line"><span>ush&gt; dhcp</span></span>
<span class="line"><span>ush&gt; ping 10.0.2.2</span></span>
<span class="line"><span>ush&gt; lsblk             (or: disk-tool, and pick it from the menu)</span></span></code></pre></div><p>用 UEFI 而非 BIOS：<code>make run-uefi</code>。Windows 宿主机： <code>build.ps1</code>（WSL2/MSYS2）。完整指南：<a href="./BUILDING.html">BUILDING.md</a>。</p><h2 id="下载" tabindex="-1">下载 <a class="header-anchor" href="#下载" aria-label="Permalink to &quot;下载&quot;">​</a></h2><p>两个频道出自同一条字节可复现流水线——都在 <a href="https://github.com/cubestudio-dev/OpenCubeOS/releases" target="_blank" rel="noreferrer">GitHub releases 页</a> 并镜像在<a href="https://ocos.cubestudio.cn/download.html" target="_blank" rel="noreferrer">网站下载页</a>：</p><table tabindex="0"><thead><tr><th>频道</th><th>资产</th></tr></thead><tbody><tr><td><strong>development preview</strong></td><td><code>opencube-&lt;version&gt;.iso</code>（启动 OCBL → OCOS → ush）</td></tr><tr><td><strong>2.2.0</strong>（stable，2.x 线）</td><td><code>opencube-2.2.0.iso</code> · <code>opencube-2.2.0-src.zip</code>（确定性源码）· <code>opencube-2.2.0-update.tar.gz</code>（OTA）</td></tr></tbody></table><p>每份发布说明携带每个资产的 SHA256；网站、 Release 与私有镜像持有逐字节一致的副本。</p><h2 id="文档" tabindex="-1">文档 <a class="header-anchor" href="#文档" aria-label="Permalink to &quot;文档&quot;">​</a></h2><ul><li><a href="./BUILDING.html">BUILDING.md</a>——在 Linux/Windows 上构建、QEMU、 交叉编译（ARM64/RISC-V shell）、可复现验证</li><li><a href="./ARCHITECTURE.html">ARCHITECTURE.md</a>——L0/L1 架构，自顶向下</li><li><a href="./INTERFACES.html">INTERFACES.md</a>——按归属划分的命令面和 L1SVC 服务表 （从树生成：<code>make api-docs</code>）</li><li><a href="./FAQ.html">FAQ.md</a>——常见问题</li><li><a href="./CONTRIBUTING.html">CONTRIBUTING.md</a>——基本规则与 PR 门槛</li><li>完整文档中心（带大应用 指南的用户手册、开发者手册、驱动上线指南、内部机制）： <strong><a href="https://ocos.cubestudio.cn/docs/" target="_blank" rel="noreferrer">https://ocos.cubestudio.cn/docs/</a></strong></li></ul><h2 id="数据" tabindex="-1">数据 <a class="header-anchor" href="#数据" aria-label="Permalink to &quot;数据&quot;">​</a></h2><p>下列数字全部在构建时经机器验证 （<code>make api-docs</code> 写 <code>docs/data/*.json</code>；每项都引用了 README 验证命令）：</p><ul><li><strong>源代码</strong>：764 个文件 158,474 行——ocos/（内核、 驱动、服务、接口、l1apps）+ ocbl/ + ocire/，含头文件、 排除生成的数据块（生成器口径： <code>tools/gen_api_docs.py</code> 的 <code>STAT_DIRS</code>/<code>STAT_EXCLUDE</code>）。 验证： <code>python3 tools/gen_api_docs.py &amp;&amp; python3 -c &quot;import json;d=json.load(open(&#39;docs/data/stats.json&#39;));print(sum(v[&#39;lines&#39;] for v in d[&#39;dirs&#39;].values()))&quot;</code></li><li><strong>命令</strong>：共 296 条——284 个 Ring-3 注册表应用（一条命令 = 一个应用 = <code>ocos/l1apps/</code> 下一个文件夹，含 8 个合并 大应用）+ 12 个 ush 内建 + L0 里 0 条。注册表下限由回归 门禁强制（&gt;= 276）。</li><li><strong>L1SVC 服务面</strong>：20 个类别 / 208 个编号操作——精确 表格见 <a href="./INTERFACES.html">INTERFACES.md</a>。</li><li><strong>系统调用</strong>：54 个——验证： <code>grep -c &#39;#define SYS_&#39; ocos/services/sysapi/interface/svc_sysapi_syscall.h</code></li><li><strong>CI</strong>：每次推送都绿——构建、ISO、打包、宿主机测试和 可复现性门禁 （<code>.github/workflows/build.yml</code>）。</li></ul><h2 id="许可" tabindex="-1">许可 <a class="header-anchor" href="#许可" aria-label="Permalink to &quot;许可&quot;">​</a></h2><p>Apache 2.0——见 <a href="./LICENSE.html">LICENSE</a>。每个源文件携带 <code>SPDX-License-Identifier: Apache-2.0</code>。</p><p>Copyright 2026 cubestudio-dev &lt;cubestudio@qq.com&gt;</p>`,24)])])}const g=t(n,[["render",d]]);export{u as __pageData,g as default};
